def normalize_valuation(adapter_results,config_thresholds=None):
    rows=[]
    for r in adapter_results:
        if r["status"]=="known_blocked":rows.append({"ticker":r["ticker"],"valuation_status":"blocked","market_cap_normalized":None,"pe_normalized":None,"ps_normalized":None,"pb_normalized":None,"currency":"N/A","metrics_normalized":0,"metrics_missing":r.get("metrics_missing",[])});continue
        rows.append({"ticker":r["ticker"],"market":r["market"],"valuation_status":r["status"],"market_cap_normalized":r.get("market_cap") or "not_available","pe_normalized":r.get("pe_value") or "not_available","ps_normalized":r.get("ps_value") or "not_available","pb_normalized":r.get("pb_value") or "not_available","ev_revenue":r.get("ev_revenue") or "not_available","ev_ebitda":r.get("ev_ebitda") or "not_available","currency":r.get("currency",""),"metrics_available":r.get("metrics_available",[]),"metrics_missing":r.get("metrics_missing",[]),"source":r.get("data_source","")})
    currency_mix={"CNY":sum(1 for r in adapter_results if r["market"]=="CN_A"),"HKD":sum(1 for r in adapter_results if r["market"]=="HK"),"USD":sum(1 for r in adapter_results if r["market"]=="US"),"N/A":sum(1 for r in adapter_results if r["status"]=="known_blocked")}
    return {"phase85_valuation_normalization":{"tickers_checked":len(rows),"metrics_normalized":sum(1 for r in rows if r["valuation_status"] in["available","partial"]),"metrics_missing_or_low_confidence":sum(1 for r in rows if r["valuation_status"] in["unavailable","blocked"]),"currency_mix":currency_mix,"rows":rows,"mock_used":False,"fixture_used":False}}
